test_prefix:
@Test
public void testSimpleStreamFilter_1_oe() {
    final List<String> input = Arrays.asList("1", "2", "3", "4", "5", "6");
    final List<Integer> output = Functions.stream(input)
            .map(Integer::valueOf)
            .filter(i -> (i.intValue() %2 == 0))
            .collect(Collectors.toList());
    assertEvenNumbers(output);
}

custom_assert_method:
private void assertEvenNumbers(final List<Integer> output) {
    assertEquals(3, output.size());
    for (int i = 0;  i < 3;  i++) {
        assertEquals((i+1)*2, output.get(i).intValue());
    }
}

test_prefix:
@TestFactory
public Stream<DynamicTest> simpleStreamFilterFailing_1_oe() {
    final List<String> input = Arrays.asList("1", "2", "3", "4", "5", "6");
    final List<Integer> output = Functions.stream(input)
            .map(Integer::valueOf)
            .filter(asIntPredicate(null))
            .collect(Collectors.toList());
    assertEvenNumbers(output);
}

custom_assert_method:
private void assertEvenNumbers(final List<Integer> output) {
    assertEquals(3, output.size());
    for (int i = 0;  i < 3;  i++) {
        assertEquals((i+1)*2, output.get(i).intValue());
    }
}

